// ── SÉCURITÉ : Anti-Prompt Injection + Limite taille ──────────────────────
function sanitizeInput(text) {
  if (!text || typeof text !== 'string') return text;

  // Limite taille : 50 000 chars max (environ 12 500 tokens)
  if (text.length > 50000) {
    text = text.substring(0, 50000) + '\n[TRONQUÉ — limite 50K chars atteinte]';
  }

  // Anti-prompt injection : neutraliser les tentatives d'override
  const injectionPatterns = [
    /ignore\s+(all\s+)?previous\s+instructions?/gi,
    /ignore\s+(toutes?\s+)?les?\s+instructions?\s+précédentes?/gi,
    /you\s+are\s+now\s+a/gi,
    /tu\s+es\s+maintenant/gi,
    /\[SYSTEM\]/gi,
    /\[INST\]/gi,
    /<\|system\|>/gi,
    /\[\[reset\]\]/gi,
  ];

  for (const pattern of injectionPatterns) {
    text = text.replace(pattern, '[FILTRÉ]');
  }

  return text;
}

